#ifndef STUDY_CHECK_HPP
#define STUDY_CHECK_HPP
#include <exception>
#include <functional>
#include <iostream>
#include <stdexcept>
#include <utility>

// 한 프로그램에서 실제로 확인한 조건의 수를 센다.
// 이 카운터는 경로 커버리지나 독립 기능 수를 측정하지 않는다.
class Checks {
    int count_{};
public:
    void Expect(bool condition, const char* label) {
        ++count_;
        if (!condition) throw std::runtime_error(label);
    }
    template<class E, class F> void Throws(F&& f, const char* label) {
        bool matched = false;
        try { std::invoke(std::forward<F>(f)); }
        catch (const E&) { matched = true; }
        // 예외를 예상하는 실험도 Expect를 한 번 호출한다.
        // E와 무관한 예외는 여기서 잡지 않고 바깥 실행 경계로 전달한다.
        Expect(matched, label);
    }
    int Count() const noexcept { return count_; }
};

template<class F> int Run(const char* name, F&& test) {
    try {
        Checks checks;
        std::invoke(std::forward<F>(test), checks);
        std::cout << "PASS " << name << ": " << checks.Count() << " checks\n";
        return 0;
    } catch (const std::exception& e) {
        std::cerr << "FAIL " << name << ": " << e.what() << '\n';
        return 1;
    }
}
#endif

#include "check.hpp"
#include <algorithm>
#include <cstddef>
#include <initializer_list>
#include <memory>
#include <new>
#include <type_traits>
#include <vector>

// 실제 메모리를 고갈시키지 않고 다음 Copy 호출의 실패 경로를 선택한다.
struct FailPoint { inline static bool next_copy = false; };

// 불변식: size가 0일 때에만 data가 null이다. int 전용 학습 구현이다.
// 실제 프로젝트에서는 먼저 std::vector 같은 소유 타입을 선택한다.
class IntBuffer {
    std::size_t size_{};
    std::unique_ptr<int[]> data_;

    static std::unique_ptr<int[]> Copy(const IntBuffer& source) {
        // 플래그를 소비한 뒤 예외를 던진다. 대상 버퍼의 보장과 이 실험 플래그는 별개다.
        if (std::exchange(FailPoint::next_copy, false)) throw std::bad_alloc{};
        if (source.size_ == 0) return {};
        auto result = std::make_unique<int[]>(source.size_);
        std::copy_n(source.data_.get(), source.size_, result.get());
        return result;
    }

public:
    IntBuffer() = default;
    explicit IntBuffer(std::initializer_list<int> values)
        : size_(values.size()), data_(size_ ? std::make_unique<int[]>(size_) : nullptr) {
        if (size_ != 0) std::copy(values.begin(), values.end(), data_.get());
    }
    ~IntBuffer() = default;

    // 서로 다른 배열을 소유하도록 깊은 복사한다.
    IntBuffer(const IntBuffer& other) : size_(other.size_), data_(Copy(other)) {}
    IntBuffer& operator=(const IntBuffer& other) {
        if (this != &other) {
            // 준비가 실패하면 이 객체는 그대로다. 성공한 임시값과만 상태를 교체한다.
            IntBuffer temporary(other);
            Swap(temporary);
        }
        return *this;
    }

    IntBuffer(IntBuffer&& other) noexcept
        : size_(std::exchange(other.size_, 0)), data_(std::move(other.data_)) {}
    IntBuffer& operator=(IntBuffer&& other) noexcept {
        // 이 타입은 자기 이동에서도 기존 값을 유지하도록 직접 계약을 정했다.
        if (this != &other) {
            data_ = std::move(other.data_);
            size_ = std::exchange(other.size_, 0);
        }
        return *this;
    }

    void Swap(IntBuffer& other) noexcept {
        using std::swap;
        swap(size_, other.size_);
        data_.swap(other.data_);
    }
    friend void swap(IntBuffer& a, IntBuffer& b) noexcept { a.Swap(b); }
    std::size_t Size() const noexcept { return size_; }
    bool Valid() const noexcept { return (size_ == 0) == (data_ == nullptr); }
    int& At(std::size_t index) {
        if (index >= size_) throw std::out_of_range("index");
        return data_[index];
    }
    const int& At(std::size_t index) const {
        if (index >= size_) throw std::out_of_range("index");
        return data_[index];
    }
};

// vector가 소유권을 관리하므로 직접 복사·이동·소멸 코드를 작성하지 않는다.
struct RuleZero { std::vector<int> values; };

struct CopyOnly {
    int* copies;
    explicit CopyOnly(int& value) : copies(&value) {}
    CopyOnly(const CopyOnly& other) : copies(other.copies) { ++*copies; }
};

struct Immovable {
    Immovable() = default;
    Immovable(const Immovable&) = delete;
    Immovable(Immovable&&) = delete;
};

// C++17 이후 같은 타입 prvalue로 결과 객체를 직접 만든다. 이름 붙은 지역값 NRVO와 다르다.
Immovable Make() { return Immovable{}; }
static_assert(std::is_nothrow_move_constructible_v<IntBuffer>);
static_assert(std::is_nothrow_move_assignable_v<IntBuffer>);

int main() {
    return Run("ownership", [](Checks& c) {
        RuleZero a{{1,2,3}};
        auto b = a;
        b.values[0] = 9;
        c.Expect(a.values[0] == 1, "rule zero copies values");

        IntBuffer source({10,20,30});
        IntBuffer copy(source);
        copy.At(0) = 77;
        c.Expect(source.At(0) == 10 && copy.At(0) == 77, "deep copy");

        IntBuffer target({5});
        FailPoint::next_copy = true;
        c.Throws<std::bad_alloc>([&] { target = source; }, "injected copy failure");
        c.Expect(target.Size() == 1 && target.At(0) == 5 && target.Valid(), "strong guarantee");
        target = source;
        c.Expect(target.At(2) == 30, "copy assignment");
        IntBuffer& alias = target;
        target = alias;
        c.Expect(target.At(0) == 10, "self copy");

        IntBuffer moved(std::move(target));
        // 비어 있는 이동 원본은 이 IntBuffer의 명시적 계약이며 모든 타입의 공통 결과가 아니다.
        c.Expect(target.Size() == 0 && target.Valid(), "move source");
        c.Expect(moved.At(2) == 30 && moved.Valid(), "move destination");
        IntBuffer& moved_alias = moved;
        moved = std::move(moved_alias);
        c.Expect(moved.At(2) == 30 && moved.Valid(), "self move contract");
        IntBuffer empty;
        empty = std::move(moved);
        c.Expect(moved.Size() == 0 && empty.Size() == 3 && moved.Valid(), "move assignment");
        c.Throws<std::out_of_range>([&] { (void)moved.At(0); }, "moved source bounds");

        int copies{};
        CopyOnly old(copies);
        // std::move는 이동 생성자 호출을 강제하지 않는다. 여기서는 const& 복사 생성자가 선택된다.
        CopyOnly copied(std::move(old));
        (void)copied;
        c.Expect(copies == 1, "std::move can copy");
        auto elided = Make();
        (void)elided;
        // 삭제된 복사·이동으로도 위 선언이 컴파일되는 사실이 핵심 증거다.
        // 이 Expect(true)는 원본 실행 카운터에 포함되며 추가 동작을 검증하지 않는다.
        c.Expect(true, "prvalue construction despite deleted copy and move");
    });
}

#include "check.hpp"
#include <memory>
#include <string>
#include <vector>

struct State {
    std::vector<int> inventory;
    std::string scene;
};

class GameState {
    std::unique_ptr<State> state_ = std::make_unique<State>(State{{1,2},"old"});
public:
    const State& Get() const noexcept { return *state_; }
    void Transition(std::string scene, bool fail_validation = false) {
        // 별도 후보에 변경을 준비한다. 실패 전에는 현재 소유 상태를 건드리지 않는다.
        auto candidate = std::make_unique<State>(*state_);
        candidate->inventory.push_back(3);
        candidate->scene = std::move(scene);
        if (fail_validation || candidate->scene.empty()) throw std::runtime_error("validation");
        // 준비·검증 뒤 noexcept인 소유권 교체를 한다. 이전 상태는 candidate가 정리한다.
        // 파일·네트워크 롤백이나 스레드 사이의 원자적 공개를 구현한 것은 아니다.
        state_.swap(candidate);
    }
};

struct Resource {
    inline static int alive{};
    Resource() { ++alive; }
    ~Resource() { --alive; }
};
int FailPriority() { throw std::runtime_error("priority"); }
void Consume(std::unique_ptr<Resource>, int) {}

int main() {
    return Run("transaction", [](Checks& c) {
        GameState game;
        c.Throws<std::runtime_error>([&] { game.Transition("new", true); }, "late failure");
        c.Expect(game.Get().scene == "old" && game.Get().inventory == std::vector<int>({1,2}), "strong guarantee");
        game.Transition("new");
        c.Expect(game.Get().scene == "new" && game.Get().inventory.size() == 3, "commit");

        // 인수 평가 순서는 고정하지 않는다. Resource가 생성되지 않을 수도 있다.
        // 먼저 생성되었다면 unique_ptr 임시 객체가 예외 전파 중 자원을 정리한다.
        c.Throws<std::runtime_error>([] { Consume(std::make_unique<Resource>(), FailPriority()); }, "argument failure");
        c.Expect(Resource::alive == 0, "RAII despite argument failure");

        auto owner = std::make_shared<Resource>();
        std::weak_ptr<Resource> observer = owner;
        // weak_ptr 자체는 소유 수를 늘리지 않는다. lock으로 얻은 shared_ptr은 소유한다.
        c.Expect(!observer.expired() && observer.lock() != nullptr, "weak lock");
        owner.reset();
        c.Expect(observer.expired() && !observer.lock(), "weak not owning");
        c.Expect(Resource::alive == 0, "reclaimed");
    });
}

#include "check.hpp"
#include <string>
#include <string_view>
#include <type_traits>
#include <vector>
// 원본 동작을 보존하고 API 계약을 한국어로 설명한 주석판이다.
// explicit은 double에서 Seconds로의 암시적 변환을 막고, 직접 생성은 허용한다.
// 조건상 음수·NaN·3600 초과를 거부하지만 아래 실제 입력은 0.016과 -1.0뿐이다.
class Seconds {
    double value_;
public:
    explicit Seconds(double value) : value_(value) {
        if (!(value >= 0.0) || value > 3600.0) throw std::invalid_argument("seconds");
    }
    double Value() const noexcept { return value_; }
};
// 컴파일 시점 검사 한 개다. 런타임 7회와 별도로 집계한다.
static_assert(!std::is_convertible_v<double, Seconds>);
// View는 소유하지 않는 string_view다. 반환된 뷰의 수명은 Label 내부 문자열에 달려 있다.
// 두 rvalue 오버로드 삭제로 임시 Label에서 View를 직접 얻는 호출을 막는다.
// lvalue Label을 나중에 파괴하거나 문자열을 바꾸는 상황까지 자동으로 안전해지는 것은 아니다.
class Label {
    std::string text_;
public:
    explicit Label(std::string text) : text_(std::move(text)) {}
    std::string_view View() const & noexcept { return text_; }
    std::string_view View() && = delete;
    std::string_view View() const && = delete;
    // 소유 문자열을 값으로 반환하므로 임시 Label이 사라진 뒤에도 결과를 사용할 수 있다.
    std::string Copy() const { return text_; }
};
// 아래 연산자는 작은 정수로만 실행한다. 산술 범위 검증은 이 실험의 목적이 아니다.
// Small integers only: arithmetic-range validation is not this experiment's purpose.
class Counter {
    int value_{};
public:
    Counter(int value = 0) : value_(value) {}
    int Value() const noexcept { return value_; }
    Counter& operator+=(const Counter& rhs) { value_ += rhs.value_; return *this; }
    // 왼쪽 피연산자는 값으로 복사하고 +=를 재사용한다.
    // 비멤버 함수이므로 Counter가 포함된 표현식에서 양쪽 피연산자의 암시적 변환을 사용할 수 있다.
    friend Counter operator+(Counter lhs, const Counter& rhs) { lhs += rhs; return lhs; }
};
// 각 Quantity<T>에 대응하는 비멤버 friend를 클래스 안에 정의한다.
// 이 hidden friend는 Quantity가 인자로 등장할 때 ADL로 찾으며, int 인자의 Quantity 변환도 가능하다.
template<class T> class Quantity {
    T value_;
public:
    Quantity(T value) : value_(value) {}
    T Value() const { return value_; }
    friend Quantity operator+(Quantity a, Quantity b) { return Quantity(a.value_ + b.value_); }
};
// 정상 경로의 호출은 Expect 6회 + Throws 1회, 총 7회다.
int main() { return Run("interfaces", [](Checks& c) {
    Seconds dt(0.016); c.Expect(dt.Value() == 0.016, "explicit valid duration");
    c.Throws<std::invalid_argument>([] { Seconds invalid(-1.0); }, "negative duration");
    // fixed는 iterator 객체가 const인 경우다. 위치는 못 바꾸지만 가리킨 int는 수정할 수 있다.
    // readonly는 const_iterator이므로 원소를 수정할 수 없고, iterator 객체 자체는 이동할 수 있다.
    std::vector<int> data{1,2}; const auto fixed = data.begin(); *fixed = 7;
    auto readonly = data.cbegin(); ++readonly;
    c.Expect(data.front() == 7 && *readonly == 2, "const iterator vs const_iterator");
    Label label("player"); c.Expect(label.View() == "player", "borrow lvalue");
    // 임시 Label의 View 대신 소유한 Copy 결과를 받는다. 댕글링 뷰를 실제로 역참조하지 않는다.
    const auto copy = Label("temporary").Copy(); c.Expect(copy == "temporary", "owned result");
    // 양쪽 방향을 작은 값으로 확인한다. signed overflow 같은 위험 입력은 실행하지 않는다.
    Counter count(3); c.Expect((count+2).Value() == 5 && (2+count).Value() == 5, "symmetric conversion");
    Quantity<int> q(4); c.Expect((q+3).Value() == 7 && (3+q).Value() == 7, "hidden friend");
}); }

#ifndef STUDY_PIMPL_HPP
#define STUDY_PIMPL_HPP
#include <memory>
#include <string>

// 공개 선언은 Impl의 존재만 알리고, 구체적인 데이터 배치는 pimpl.cpp로 숨긴다.
// 헤더 이용자가 Impl 정의 없이 Settings를 선언·사용하는 경계를 보여 준다.
// 이 예제만으로 배포 라이브러리의 ABI 호환성까지 검증한 것은 아니다.
class Settings {
    struct Impl;
    // unique_ptr 멤버의 선언에는 불완전 타입을 사용할 수 있다.
    // Impl의 삭제가 필요한 연산은 완전한 정의를 볼 수 있는 .cpp에 둔다.
    std::unique_ptr<Impl> impl_;
public:
    explicit Settings(std::string name);
    // 이 헤더 안에서 = default로 정의하지 않고, Impl 정의 뒤에서 정의한다.
    ~Settings();
    Settings(Settings&&) noexcept;
    Settings& operator=(Settings&&) noexcept;

    // 소유 핸들만 복사하지 않고 별도 Impl을 만드는 값 복사 계약이다.
    // unique_ptr 자체는 복사할 수 없으므로 구현에서 이 동작을 직접 정의한다.
    Settings(const Settings&);
    Settings& operator=(const Settings&);

    // 새 Impl을 준비한 뒤 교체한다. 비어 있는 이동 후 객체도 다시 채울 수 있다.
    void Rename(std::string name);
    // 내부 문자열의 참조나 뷰가 아니라 소유하는 std::string 값을 반환한다.
    // impl_가 없을 때는 logic_error를 던지는 계약을 구현에 둔다.
    std::string Name() const;
    bool Empty() const noexcept;
    // ADL로 찾는 비멤버 swap은 두 소유 핸들만 교환한다.
    friend void swap(Settings&, Settings&) noexcept;
};
#endif

#include "pimpl.hpp"
#include <stdexcept>
#include <utility>

// 실제 데이터 정의는 이 번역 단위에서만 보인다.
struct Settings::Impl { std::string name; };

Settings::Settings(std::string name) : impl_(std::make_unique<Impl>(Impl{std::move(name)})) {}

// 이 지점에서는 Impl이 완전하므로 unique_ptr의 삭제 동작을 구성할 수 있다.
Settings::~Settings() = default;
// 기본 이동은 unique_ptr의 소유권 이동이다. 정상적인 다른 객체로의 이동 뒤에는
// 원본 핸들이 비게 된다. 테스트는 이동 생성 경로를 실행한다.
Settings::Settings(Settings&&) noexcept = default;
Settings& Settings::operator=(Settings&&) noexcept = default;

// 원본이 차 있으면 별도 Impl과 문자열 값을 복사하고, 비었으면 비어 있게 복사한다.
// 현재 정상 테스트가 확인하는 것은 차 있는 원본을 복사한 뒤 각 이름을 바꾸는 경로다.
Settings::Settings(const Settings& other) : impl_(other.impl_ ? std::make_unique<Impl>(*other.impl_) : nullptr) {}

Settings& Settings::operator=(const Settings& other) {
    if (this != &other) {
        // 후보 복사가 실패하면 아직 *this를 변경하지 않았다.
        // 복사가 끝난 뒤 noexcept swap으로 교체하고, copy가 이전 상태를 정리한다.
        // 이 구조의 강한 예외 보장을 설명하되, 해당 테스트에서 할당 실패를 주입하지는 않는다.
        Settings copy(other);
        swap(*this, copy);
    }
    return *this;
}

void Settings::Rename(std::string name) {
    // 인자 준비와 후보 생성이 완료될 때까지 기존 impl_는 그대로다.
    auto candidate = std::make_unique<Impl>(Impl{std::move(name)});
    impl_.swap(candidate);
    // candidate가 이전 Impl을 소유한 채 범위를 벗어나 정리한다.
    // 파일·네트워크 부수 효과나 동시 접근을 다루는 트랜잭션은 아니다.
}

std::string Settings::Name() const {
    // 이동 후 비어 있는 상태를 유효한 상태로 인정하되, Name 접근은 명시적으로 거부한다.
    if (!impl_) throw std::logic_error("empty moved-from settings");
    // 값 복사 반환이므로 호출자는 Settings와 별도의 문자열 수명을 갖는다.
    return impl_->name;
}

bool Settings::Empty() const noexcept { return !impl_; }
// Impl의 문자열을 하나씩 교환하지 않고, 두 소유 포인터를 교환한다.
void swap(Settings& a, Settings& b) noexcept { a.impl_.swap(b.impl_); }

#include "check.hpp"
#include "pimpl.hpp"
#include <type_traits>

// 실행 시 검사 여섯 회와 별개인 컴파일 시점 성질 확인이다.
// 이 번역 단위는 Impl의 데이터 정의를 보지 않고 공개 헤더만 사용한다.
static_assert(std::is_nothrow_move_constructible_v<Settings>);

int main() { return Run("pimpl", [](Checks& c) {
    Settings a("old");
    Settings b = a;
    b.Rename("new");
    // 1. Rename 뒤 b의 새 이름과 a의 기존 이름을 관찰한다.
    // 복사 시 별도 Impl을 생성한다는 근거는 복사 생성자의 make_unique 코드다.
    // Rename 자체도 후보 Impl로 교체하므로 이 결과만으로 포인터 분리를 증명하지 않는다.
    c.Expect(a.Name() == "old" && b.Name() == "new", "deep pimpl copy");

    // std::move 자체는 변환이다. 여기서는 선택된 이동 생성자가 소유권을 옮긴다.
    Settings moved = std::move(a);
    // 2. 이동 원본의 Empty와 대상의 이름을 함께 확인한다.
    c.Expect(a.Empty() && moved.Name() == "old", "move contract");
    // 3. 빈 객체에 Name을 호출하는 계약 위반은 logic_error로 보고한다.
    c.Throws<std::logic_error>([&] { (void)a.Name(); }, "empty contract");

    a.Rename("restored");
    // 4. 이동 후 객체도 새 이름으로 복구할 수 있다.
    c.Expect(a.Name() == "restored", "restore moved-from");
    // std::swap 후보를 열어 두고, 인자 타입과 연관된 비멤버 swap을 ADL로 찾는다.
    using std::swap;
    swap(a,b);
    // 5. 두 객체의 이름이 바뀌었는지 확인한다.
    c.Expect(a.Name() == "new" && b.Name() == "restored", "ADL swap");

    b = moved;
    // 6. 복사 대입의 정상 경로를 확인한다. 자기 대입·이동 대입·빈 원본 복사나
    // 후보 복사 실패를 이 여섯 회에서 각각 실행했다고 해석하지 않는다.
    c.Expect(b.Name() == "old", "assignment");
}); }
